import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.Bwt6MOeu.js";const u=JSON.parse('{"title":"Auth and Connections","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auth-and-connections.md","filePath":"guide/auth-and-connections.md"}'),o={name:"guide/auth-and-connections.md"};function r(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="auth-and-connections" tabindex="-1">Auth and Connections <a class="header-anchor" href="#auth-and-connections" aria-label="Permalink to &quot;Auth and Connections&quot;">​</a></h1><p>SocioProphet presents a single platform identity and then manages provider connections as capabilities.</p><p>Users do not need to assemble agents, providers, callbacks, keys, and recovery flows manually. They sign into SocioProphet once, then connect providers under that workspace identity.</p><h2 id="platform-sign-in" tabindex="-1">Platform sign-in <a class="header-anchor" href="#platform-sign-in" aria-label="Permalink to &quot;Platform sign-in&quot;">​</a></h2><p>Platform sign-in is the first layer of identity:</p><ul><li>passkey-first when available</li><li>magic-link fallback</li><li>workspace and role context</li><li>audit-aware identity surface</li></ul><p>This is the user&#39;s anchor identity. Provider-specific auth does not replace it.</p><h2 id="provider-connections" tabindex="-1">Provider connections <a class="header-anchor" href="#provider-connections" aria-label="Permalink to &quot;Provider connections&quot;">​</a></h2><p>Providers are represented as capability backends:</p><ul><li>OpenAI / Codex for coding capability</li><li>Anthropic for research capability</li><li>browser automation for login-required browsing</li><li>local runtime for private or offline capability</li></ul><p>The user sees connection state, health, and recovery. They do not have to think in terms of scattered credential surfaces.</p><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>The orchestration burden is the product value.</p><p>Most users will never successfully assemble:</p><ul><li>multiple providers</li><li>multiple callback flows</li><li>multiple auth states</li><li>degraded fallback behavior</li></ul><p>SocioProphet absorbs that complexity and turns it into a governed identity-and-capability surface.</p>',16)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
